'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var pkg = require( './../package.json' ).name;
var dorm2r = require( './../lib/ndarray.js' );


// VARIABLES //

var SIDES = [
	'left',
	'right'
];
var TRANS = [
	'no-transpose',
	'transpose'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} side - specifies the side of multiplication
* @param {string} trans - specifies the operation to be performed
* @param {PositiveInteger} N - number of rows/columns in matrix C
* @returns {Function} benchmark function
*/
function createBenchmark( side, trans, N ) {
	var work;
	var tau;
	var A;
	var C;

	A = uniform( N*N, 0.01, 0.1, {
		'dtype': 'float64'
	});
	tau = uniform( N, 0.01, 0.1, {
		'dtype': 'float64'
	});
	C = uniform( N*N, 0.01, 0.1, {
		'dtype': 'float64'
	});
	work = new Float64Array( N );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dorm2r( side, trans, N, N, N, A, N, 1, 0, tau, 1, 0, C, N, 1, 0, work, 1, 0 ); // eslint-disable-line max-len
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var trans;
	var side;
	var min;
	var max;
	var N;
	var f;
	var i;
	var j;
	var k;
	var l;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( k = 0; k < SIDES.length; k++ ) {
		side = SIDES[ k ];
		for ( l = 0; l < TRANS.length; l++ ) {
			trans = TRANS[ l ];
			for ( i = min; i <= max; i++ ) {
				N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
				j = 1;
				while ( j <= N ) {
					f = createBenchmark( side, trans, N );
					bench( pkg+'::square_matrix:ndarray:side='+side+',trans='+trans+',M='+N+',N='+N+',K='+N, f );
					j *= 2;
				}
			}
		}
	}
}

main();
